s=open('pmeasure3.py').read()
old = s[s.index("from scipy.spatial import cKDTree"):s.index("def held_piece3(")]
new = '''from scipy.spatial import cKDTree
def cluster3d(P, eps=0.008):
    if len(P)==0: return []
    keys = np.round(np.asarray(P)/eps).astype(np.int64)
    uniq, inv = np.unique(keys, axis=0, return_inverse=True)
    n = len(uniq)
    idx = {tuple(int(v) for v in k): i for i,k in enumerate(uniq)}
    parent = list(range(n))
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[ra]=rb
    offs = [(dx,dy,dz) for dx in (-1,0,1) for dy in (-1,0,1) for dz in (-1,0,1)]
    for i,k in enumerate(uniq):
        for (dx,dy,dz) in offs:
            j = idx.get((int(k[0])+dx, int(k[1])+dy, int(k[2])+dz))
            if j is not None: union(i,j)
    roots = np.array([find(int(inv[i])) for i in range(len(P))])
    groups = {}
    for i,r in enumerate(roots):
        groups.setdefault(int(r), []).append(i)
    return [np.array(v) for v in groups.values()]

'''
s = s.replace(old, new)
open('pmeasure3.py','w').write(s)
print("patched")

